            lcfg_mkdir_p(q);
            _snprintf_s(q, sizeof q, _TRUNCATE, "%s/packs.json", pkd);
            write_file(q, "{ \"version\": 1, \"order\": [\n"
                          "  { \"id\": \"t.ta\", \"file\": \"ta\" },\n"
                          "  { \"id\": \"t.tb\", \"file\": \"tb\" },\n"
                          "  { \"id\": \"t.fx\", \"file\": \"fx\" },\n"
                          "  { \"id\": \"bad\", \"file\": \"bad\" } ],\n"
                          "  \"level\": \"x4\" }");
