                static const struct { const char *path; int rc, ed, us; } k63[] = {
                    { W220_ISO_US, 0, LCFG_ED_US, 1 },
                    { W220_ISO, 0, LCFG_ED_EU, 0 },
                    { W220_ISO_JP, 4, LCFG_ED_OTHER, 0 },
                };
                char why63[300] = "", hp[1200], args[1600], e63[600], keep63[16];
